1	use callisto_model::{Severity, Version, VersionGrammar};
2	
3	/// Trait for version arithmetic per versioning grammar.
4	pub trait Versioning: Send + Sync {
5	    fn grammar(&self) -> VersionGrammar;
6	    fn bump(&self, current: &Version, severity: Severity) -> Result<Version, BumpError>;
7	    fn bump_prerelease(
8	        &self,
9	        base: &Version,
10	        severity: Severity,
11	        tag: &str,
12	        current: &Version,
13	    ) -> Result<Version, BumpError>;
14	}
15	
16	/// SemVer versioning arithmetic implementation matching @changesets/cli semantics.
17	pub struct SemVerVersioning;
18	
19	static SEMVER_VERSIONING: SemVerVersioning = SemVerVersioning;
20	
21	/// PEP 440 versioning arithmetic implementation.
22	///
23	/// Bump semantics (deliberate, see the test matrix below):
24	/// - Release segment is `major.minor.patch`, matching SemVer's shape; any
25	///   4th+ segment is dropped by a bump.
26	/// - Epoch (`N!`) has no SemVer analogue -- carries through unchanged.
27	/// - Pre-releases (`aN`/`bN`/`rcN`) and dev-releases (`.devN`) sort
28	///   *before* the final release (PEP 440: `devN < aN < bN < rcN < final`),
29	///   so a bump finalizes them in place like the SemVer prerelease branch:
30	///   `Patch` drops the tag; `Minor`/`Major` advance the next component up
31	///   only when the lower one is already zero.
32	/// - Post-releases (`.postN`) sort *after* the final release (`final <
33	///   .postN`), so the base release is already shipped: a bump increments
34	///   normally (as if no pre/dev/post suffix existed) and drops the post
35	///   segment, rather than continuing the post sequence.
36	/// - Local version labels (`+localsuffix`) are always dropped.
37	pub struct Pep440Versioning;
38	
39	static PEP440_VERSIONING: Pep440Versioning = Pep440Versioning;
40	
41	pub fn versioning_for(grammar: VersionGrammar) -> Option<&'static dyn Versioning> {
42	    match grammar {
43	        VersionGrammar::SemVer => Some(&SEMVER_VERSIONING),
44	        VersionGrammar::Pep440 => Some(&PEP440_VERSIONING),
45	        _ => None,
46	    }
47	}
48	
49	impl Versioning for SemVerVersioning {
50	    fn grammar(&self) -> VersionGrammar {
51	        VersionGrammar::SemVer
52	    }
53	
54	    fn bump(&self, current: &Version, severity: Severity) -> Result<Version, BumpError> {
55	        if current.grammar() != VersionGrammar::SemVer {
56	            return Err(BumpError::NotSemVer {
57	                raw: current.render().to_string(),
58	                grammar: current.grammar(),
59	            });
60	        }
61	
62	        if severity == Severity::None {
63	            return Ok(current.clone());
64	        }
65	
66	        let major = current.major().unwrap_or(0);
67	        let minor = current.minor().unwrap_or(0);
68	        let patch = current.patch().unwrap_or(0);
69	
70	        let overflow = || BumpError::Overflow {
71	            raw: current.render().to_string(),
72	        };
73	
74	        if current.is_prerelease() {
75	            let base = Version::semver(major, minor, patch);
76	            let bumped = match severity {
77	                Severity::Patch => base,
78	                Severity::Minor => {
79	                    if patch == 0 {
80	                        base
81	                    } else {
82	                        Version::semver(major, minor.checked_add(1).ok_or_else(overflow)?, 0)
83	                    }
84	                }
85	                Severity::Major => {
86	                    if minor == 0 && patch == 0 {
87	                        base
88	                    } else {
89	                        Version::semver(major.checked_add(1).ok_or_else(overflow)?, 0, 0)
90	                    }
91	                }
92	                Severity::None => current.clone(),
93	            };
94	            return Ok(bumped);
95	        }
96	
97	        let bumped = match severity {
98	            Severity::Major => Version::semver(major.checked_add(1).ok_or_else(overflow)?, 0, 0),
99	            Severity::Minor => Version::semver(major, minor.checked_add(1).ok_or_else(overflow)?, 0),
100	            Severity::Patch => Version::semver(major, minor, patch.checked_add(1).ok_or_else(overflow)?),
101	            Severity::None => current.clone(),
102	        };
103	
104	        Ok(bumped)
105	    }
106	
107	    fn bump_prerelease(
108	        &self,
109	        base: &Version,
110	        severity: Severity,
111	        tag: &str,
112	        current: &Version,
113	    ) -> Result<Version, BumpError> {
114	        if severity == Severity::None {
115	            return Ok(current.clone());
116	        }
117	
118	        let release = self.bump(base, severity)?;
119	
120	        let mut counter = 0;
121	        if current.is_prerelease() {
122	            let current_raw = current.render();
123	            if let Some((rel_part, pre_part)) = current_raw.split_once('-') {
124	                if rel_part == release.render() {
125	                    let dotted_prefix = format!("{tag}.");
126	                    if let Some(num_str) = pre_part.strip_prefix(&dotted_prefix) {
127	                        // Dotted form: e.g. "alpha.3" with tag "alpha" → num_str = "3"
128	                        if let Ok(num) = num_str.parse::<u64>() {
129	                            counter = num.checked_add(1).ok_or_else(|| BumpError::Overflow {
130	                                raw: current.render().to_string(),
131	                            })?;
132	                        }
133	                    } else if let Some(num_str) = pre_part.strip_prefix(tag) {
134	                        // Undotted form: e.g. "alpha1" with tag "alpha" → num_str = "1"
135	                        if let Ok(num) = num_str.parse::<u64>() {
136	                            counter = num.checked_add(1).ok_or_else(|| BumpError::Overflow {
137	                                raw: current.render().to_string(),
138	                            })?;
139	                        }
140	                    }
141	                }
142	            }
143	        }
144	
145	        let prerelease_str = format!("{}-{tag}.{counter}", release.render());
146	        let final_version =
147	            Version::parse(&prerelease_str, VersionGrammar::SemVer).map_err(|_err| BumpError::NotSemVer {
148	                raw: prerelease_str,
149	                grammar: VersionGrammar::SemVer,
150	            })?;
151	
152	        Ok(final_version)
153	    }
154	}
