156	impl Versioning for Pep440Versioning {
157	    fn grammar(&self) -> VersionGrammar {
158	        VersionGrammar::Pep440
159	    }
160	
161	    fn bump(&self, current: &Version, severity: Severity) -> Result<Version, BumpError> {
162	        if current.grammar() != VersionGrammar::Pep440 {
163	            return Err(BumpError::NotPep440 {
164	                raw: current.render().to_string(),
165	                grammar: current.grammar(),
166	            });
167	        }
168	
169	        if severity == Severity::None {
170	            return Ok(current.clone());
171	        }
172	
173	        let parsed = parse_pep440(current)?;
174	        let epoch = parsed.epoch();
175	        let (major, minor, patch) = release_triple(&parsed);
176	
177	        // Pre-releases and dev-releases both precede the release they're attached
178	        // to, so a bump finalizes them in place rather than continuing forward.
179	        // But a post-release segment (even combined with a dev segment, e.g.
180	        // `1.2.3.post1.dev1`) outranks the final release (PEP 440 ordering:
181	        // dev < pre < release < post), so any version carrying a post segment
182	        // must bump forward normally, same as the post-only case, never
183	        // finalize in place.
184	        let finalize_in_place = !parsed.is_post() && (parsed.is_pre() || parsed.is_dev());
185	
186	        let overflow = || BumpError::Overflow {
187	            raw: current.render().to_string(),
188	        };
189	
190	        let (new_major, new_minor, new_patch) = if finalize_in_place {
191	            match severity {
192	                Severity::Patch => (major, minor, patch),
193	                Severity::Minor => {
194	                    if patch == 0 {
195	                        (major, minor, patch)
196	                    } else {
197	                        (major, minor.checked_add(1).ok_or_else(overflow)?, 0)
198	                    }
199	                }
200	                Severity::Major => {
201	                    if minor == 0 && patch == 0 {
202	                        (major, minor, patch)
203	                    } else {
204	                        (major.checked_add(1).ok_or_else(overflow)?, 0, 0)
205	                    }
206	                }
207	                Severity::None => unreachable!("handled above"),
208	            }
209	        } else {
210	            match severity {
211	                Severity::Major => (major.checked_add(1).ok_or_else(overflow)?, 0, 0),
212	                Severity::Minor => (major, minor.checked_add(1).ok_or_else(overflow)?, 0),
213	                Severity::Patch => (major, minor, patch.checked_add(1).ok_or_else(overflow)?),
214	                Severity::None => unreachable!("handled above"),
215	            }
216	        };
217	
218	        let bumped = pep440_rs::Version::new([new_major, new_minor, new_patch]).with_epoch(epoch);
219	        render_pep440(bumped)
220	    }
221	
222	    fn bump_prerelease(
223	        &self,
224	        base: &Version,
225	        severity: Severity,
226	        tag: &str,
227	        current: &Version,
228	    ) -> Result<Version, BumpError> {
229	        if severity == Severity::None {
230	            return Ok(current.clone());
231	        }
232	
233	        let release = self.bump(base, severity)?;
234	        let release_str = release.render();
235	
236	        // PEP 440 pre-release labels are restricted to alpha/beta/rc; an arbitrary
237	        // caller-supplied tag (e.g. "next") has no PEP 440 equivalent, so it falls
238	        // back to a dev-release, the closest "not yet final" concept PEP 440 has.
239	        let letter = pep440_prerelease_letter(tag);
240	
241	        let mut counter = 0u64;
242	        let current_raw = current.render();
243	        if let Some(rest) = current_raw.strip_prefix(release_str) {
244	            let num_str = match letter {
245	                Some(letter) => rest.strip_prefix(letter),
246	                None => rest.strip_prefix(".dev"),
247	            };
248	            if let Some(num_str) = num_str {
249	                if let Ok(num) = num_str.parse::<u64>() {
250	                    counter = num.checked_add(1).ok_or_else(|| BumpError::Overflow {
251	                        raw: current.render().to_string(),
252	                    })?;
253	                }
254	            }
255	        }
256	
257	        let prerelease_str = match letter {
258	            Some(letter) => format!("{release_str}{letter}{counter}"),
259	            None => format!("{release_str}.dev{counter}"),
260	        };
261	
262	        Version::parse(&prerelease_str, VersionGrammar::Pep440).map_err(|e| BumpError::ComputedVersionInvalid {
263	            raw: prerelease_str,
264	            message: e.message,
265	        })
266	    }
267	}
268	
269	/// Maps common pre-release tag spellings to their PEP 440 letter. PEP 440 only
270	/// recognizes alpha/beta/rc pre-releases; anything else has no direct mapping.
271	fn pep440_prerelease_letter(tag: &str) -> Option<&'static str> {
272	    match tag.to_ascii_lowercase().as_str() {
273	        "a" | "alpha" => Some("a"),
274	        "b" | "beta" => Some("b"),
275	        "rc" | "c" | "pre" | "preview" => Some("rc"),
276	        _ => None,
277	    }
278	}
279	
280	fn parse_pep440(v: &Version) -> Result<pep440_rs::Version, BumpError> {
281	    v.raw()
282	        .parse::<pep440_rs::Version>()
283	        .map_err(|e| BumpError::ComputedVersionInvalid {
284	            raw: v.raw().to_string(),
285	            message: e.to_string(),
286	        })
287	}
288	
289	fn release_triple(v: &pep440_rs::Version) -> (u64, u64, u64) {
290	    let release = v.release();
291	    (
292	        release.first().copied().unwrap_or(0),
293	        release.get(1).copied().unwrap_or(0),
294	        release.get(2).copied().unwrap_or(0),
295	    )
296	}
297	
298	fn render_pep440(v: pep440_rs::Version) -> Result<Version, BumpError> {
299	    let rendered = v.to_string();
300	    Version::parse(&rendered, VersionGrammar::Pep440).map_err(|e| BumpError::ComputedVersionInvalid {
301	        raw: rendered,
302	        message: e.message,
303	    })
304	}
305	
306	pub fn bump_version(current: &Version, severity: Severity) -> Result<Version, BumpError> {
307	    SEMVER_VERSIONING.bump(current, severity)
308	}
