310	#[derive(Clone, Debug, thiserror::Error, miette::Diagnostic, PartialEq, Eq)]
311	#[non_exhaustive]
312	pub enum BumpError {
313	    #[error("bump_version requires a SemVer version; `{raw}` was parsed as {grammar:?}")]
314	    #[diagnostic(code(E035))]
315	    NotSemVer { raw: String, grammar: VersionGrammar },
316	    #[error("no versioning implementation exists for {grammar:?}")]
317	    #[diagnostic(code(E036))]
318	    UnsupportedGrammar { grammar: VersionGrammar },
319	    #[error("bump requires a PEP 440 version; `{raw}` was parsed as {grammar:?}")]
320	    #[diagnostic(code(E037))]
321	    NotPep440 { raw: String, grammar: VersionGrammar },
322	    #[error("internal error computing bumped version `{raw}`: {message}")]
323	    #[diagnostic(code(E038))]
324	    ComputedVersionInvalid { raw: String, message: String },
325	    #[error("version component overflow while bumping `{raw}`")]
326	    #[diagnostic(code(E039))]
327	    Overflow { raw: String },
328	}
