379	    // Pre-releases (aN/bN/rcN) finalize toward the base release, mirroring the
380	    // SemVer prerelease branch: a patch bump just drops the prerelease tag,
381	    // minor/major only increment when the lower component is non-zero.
382	    #[case("1.2.3a1", Severity::Patch, "1.2.3")]
383	    #[case("1.2.3a1", Severity::Minor, "1.3.0")]
