388	    // devN < aN < bN < rcN < final), so they finalize the same way pre-releases do.
389	    #[case("1.2.3.dev0", Severity::Patch, "1.2.3")]
390	    #[case("1.2.3.dev0", Severity::Minor, "1.3.0")]
391	    // Post-releases (.postN) come *after* an already-shipped final release
