    #[case("1!2.3.post1.dev1", Severity::Minor, "1!2.4.0")]
    #[case("1!2.3.post1.dev1", Severity::Major, "1!3.0.0")]
    fn test_pep440_bump_epoch_post_dev_combined(#[case] input: &str, #[case] sev: Severity, #[case] expected: &str) {
