    #[case("1.2.3+build.5", Severity::Major, "2.0.0")]
    fn test_pep440_bump_drops_local_version_label(#[case] input: &str, #[case] sev: Severity, #[case] expected: &str) {
        let v = Version::parse(input, VersionGrammar::Pep440).unwrap();
