        let cur9 = Version::parse("1.2.3-alpha9", VersionGrammar::SemVer).unwrap();
        let result9 = SEMVER_VERSIONING
            .bump_prerelease(&base, Severity::Patch, "alpha", &cur9)
            .unwrap();
