use callisto_model::{Severity, Version, VersionGrammar};

/// Trait for version arithmetic per versioning grammar.
pub trait Versioning: Send + Sync {
    fn grammar(&self) -> VersionGrammar;
    fn bump(&self, current: &Version, severity: Severity) -> Result<Version, BumpError>;
    fn bump_prerelease(
        &self,
        base: &Version,
        severity: Severity,
        tag: &str,
        current: &Version,
    ) -> Result<Version, BumpError>;
}

/// SemVer versioning arithmetic implementation matching @changesets/cli semantics.
pub struct SemVerVersioning;

static SEMVER_VERSIONING: SemVerVersioning = SemVerVersioning;

/// PEP 440 versioning arithmetic implementation.
///
/// Bump semantics (deliberate, see the test matrix below):
/// - Release segment is `major.minor.patch`, matching SemVer's shape; any
///   4th+ segment is dropped by a bump.
/// - Epoch (`N!`) has no SemVer analogue -- carries through unchanged.
/// - Pre-releases (`aN`/`bN`/`rcN`) and dev-releases (`.devN`) sort
///   *before* the final release (PEP 440: `devN < aN < bN < rcN < final`),
///   so a bump finalizes them in place like the SemVer prerelease branch:
///   `Patch` drops the tag; `Minor`/`Major` advance the next component up
///   only when the lower one is already zero.
/// - Post-releases (`.postN`) sort *after* the final release (`final <
///   .postN`), so the base release is already shipped: a bump increments
///   normally (as if no pre/dev/post suffix existed) and drops the post
///   segment, rather than continuing the post sequence.
/// - Local version labels (`+localsuffix`) are always dropped.
pub struct Pep440Versioning;

static PEP440_VERSIONING: Pep440Versioning = Pep440Versioning;

pub fn versioning_for(grammar: VersionGrammar) -> Option<&'static dyn Versioning> {
    match grammar {
        VersionGrammar::SemVer => Some(&SEMVER_VERSIONING),
        VersionGrammar::Pep440 => Some(&PEP440_VERSIONING),
        _ => None,
    }
}

impl Versioning for SemVerVersioning {
    fn grammar(&self) -> VersionGrammar {
        VersionGrammar::SemVer
    }

    fn bump(&self, current: &Version, severity: Severity) -> Result<Version, BumpError> {
        if current.grammar() != VersionGrammar::SemVer {
            return Err(BumpError::NotSemVer {
                raw: current.render().to_string(),
                grammar: current.grammar(),
            });
        }

        if severity == Severity::None {
            return Ok(current.clone());
        }

        let major = current.major().unwrap_or(0);
        let minor = current.minor().unwrap_or(0);
        let patch = current.patch().unwrap_or(0);

        let overflow = || BumpError::Overflow {
            raw: current.render().to_string(),
        };

        let (new_major, new_minor, new_patch) =
            bump_release_triple(major, minor, patch, severity, current.is_prerelease(), overflow)?;

        Ok(Version::semver(new_major, new_minor, new_patch))
    }

    fn bump_prerelease(
        &self,
        base: &Version,
        severity: Severity,
        tag: &str,
        current: &Version,
    ) -> Result<Version, BumpError> {
        if severity == Severity::None {
            return Ok(current.clone());
        }

        let release = self.bump(base, severity)?;
        let overflow = || BumpError::Overflow {
            raw: current.render().to_string(),
        };

        let mut counter_suffix = None;
        if current.is_prerelease() {
            let current_raw = current.render();
            if let Some((rel_part, pre_part)) = current_raw.split_once('-') {
                if rel_part == release.render() {
                    let dotted_prefix = format!("{tag}.");
                    counter_suffix = pre_part
                        // Dotted form: e.g. "alpha.3" with tag "alpha" → "3"
                        .strip_prefix(&dotted_prefix)
                        // Undotted form: e.g. "alpha1" with tag "alpha" → "1"
                        .or_else(|| pre_part.strip_prefix(tag));
                }
            }
        }
        let counter = next_counter(counter_suffix, overflow)?;

        let prerelease_str = format!("{}-{tag}.{counter}", release.render());
        let final_version =
            Version::parse(&prerelease_str, VersionGrammar::SemVer).map_err(|_err| BumpError::NotSemVer {
                raw: prerelease_str,
                grammar: VersionGrammar::SemVer,
            })?;

        Ok(final_version)
    }
}

impl Versioning for Pep440Versioning {
    fn grammar(&self) -> VersionGrammar {
        VersionGrammar::Pep440
    }

    fn bump(&self, current: &Version, severity: Severity) -> Result<Version, BumpError> {
        if current.grammar() != VersionGrammar::Pep440 {
            return Err(BumpError::NotPep440 {
                raw: current.render().to_string(),
                grammar: current.grammar(),
            });
        }

        if severity == Severity::None {
            return Ok(current.clone());
        }

        let parsed = parse_pep440(current)?;
        let epoch = parsed.epoch();
        let (major, minor, patch) = release_triple(&parsed);

        // Pre-releases and dev-releases both precede the release they're attached
        // to, so a bump finalizes them in place rather than continuing forward.
        // But a post-release segment (even combined with a dev segment, e.g.
        // `1.2.3.post1.dev1`) outranks the final release (PEP 440 ordering:
        // dev < pre < release < post), so any version carrying a post segment
        // must bump forward normally, same as the post-only case, never
        // finalize in place.
        let finalize_in_place = !parsed.is_post() && (parsed.is_pre() || parsed.is_dev());

        let overflow = || BumpError::Overflow {
            raw: current.render().to_string(),
        };

        let (new_major, new_minor, new_patch) =
            bump_release_triple(major, minor, patch, severity, finalize_in_place, overflow)?;

        let bumped = pep440_rs::Version::new([new_major, new_minor, new_patch]).with_epoch(epoch);
        render_pep440(bumped)
    }

    fn bump_prerelease(
        &self,
        base: &Version,
        severity: Severity,
        tag: &str,
        current: &Version,
    ) -> Result<Version, BumpError> {
        if severity == Severity::None {
            return Ok(current.clone());
        }

        let release = self.bump(base, severity)?;
        let release_str = release.render();

        // PEP 440 pre-release labels are restricted to alpha/beta/rc; an arbitrary
        // caller-supplied tag (e.g. "next") has no PEP 440 equivalent, so it falls
        // back to a dev-release, the closest "not yet final" concept PEP 440 has.
        let letter = pep440_prerelease_letter(tag);

        let overflow = || BumpError::Overflow {
            raw: current.render().to_string(),
        };
        let current_raw = current.render();
        let counter_suffix = current_raw.strip_prefix(release_str).and_then(|rest| match letter {
            Some(letter) => rest.strip_prefix(letter),
            None => rest.strip_prefix(".dev"),
        });
        let counter = next_counter(counter_suffix, overflow)?;

        let prerelease_str = match letter {
            Some(letter) => format!("{release_str}{letter}{counter}"),
            None => format!("{release_str}.dev{counter}"),
        };

        Version::parse(&prerelease_str, VersionGrammar::Pep440).map_err(|e| BumpError::ComputedVersionInvalid {
            raw: prerelease_str,
            message: e.message,
        })
    }
}

/// Maps common pre-release tag spellings to their PEP 440 letter. PEP 440 only
/// recognizes alpha/beta/rc pre-releases; anything else has no direct mapping.
fn pep440_prerelease_letter(tag: &str) -> Option<&'static str> {
    match tag.to_ascii_lowercase().as_str() {
        "a" | "alpha" => Some("a"),
        "b" | "beta" => Some("b"),
        "rc" | "c" | "pre" | "preview" => Some("rc"),
        _ => None,
    }
}

fn parse_pep440(v: &Version) -> Result<pep440_rs::Version, BumpError> {
    v.raw()
        .parse::<pep440_rs::Version>()
        .map_err(|e| BumpError::ComputedVersionInvalid {
            raw: v.raw().to_string(),
            message: e.to_string(),
        })
}

fn release_triple(v: &pep440_rs::Version) -> (u64, u64, u64) {
    let release = v.release();
    (
        release.first().copied().unwrap_or(0),
        release.get(1).copied().unwrap_or(0),
        release.get(2).copied().unwrap_or(0),
    )
}

fn render_pep440(v: pep440_rs::Version) -> Result<Version, BumpError> {
    let rendered = v.to_string();
    Version::parse(&rendered, VersionGrammar::Pep440).map_err(|e| BumpError::ComputedVersionInvalid {
        raw: rendered,
        message: e.message,
    })
}

/// Shared major.minor.patch bump arithmetic for both SemVer and PEP 440.
///
/// `finalize_in_place` selects between two mutually exclusive branches:
/// - `true` (the current version is an in-place prerelease/pre/dev tag that
///   sorts *before* its own release): finalize toward the base release.
///   `Patch` just drops the tag; `Minor`/`Major` only advance the next
///   component up when the lower component(s) are already zero -- otherwise
///   the base release is already ahead of where a fresh bump would land, so
///   the tag is dropped in place instead.
/// - `false` (an ordinary release, or one whose tag sorts *after* the release,
///   e.g. PEP 440's `.postN`): bump the matching component forward normally.
///
/// `severity` must not be `Severity::None` -- callers filter that out with an
/// early return before computing the release triple, so it is unreachable
/// here in both callers.
fn bump_release_triple(
    major: u64,
    minor: u64,
    patch: u64,
    severity: Severity,
    finalize_in_place: bool,
    overflow: impl Fn() -> BumpError,
) -> Result<(u64, u64, u64), BumpError> {
    if finalize_in_place {
        match severity {
            Severity::Patch => Ok((major, minor, patch)),
            Severity::Minor => {
                if patch == 0 {
                    Ok((major, minor, patch))
                } else {
                    Ok((major, minor.checked_add(1).ok_or_else(overflow)?, 0))
                }
            }
            Severity::Major => {
                if minor == 0 && patch == 0 {
                    Ok((major, minor, patch))
                } else {
                    Ok((major.checked_add(1).ok_or_else(overflow)?, 0, 0))
                }
            }
            Severity::None => unreachable!("callers return early on Severity::None before reaching this point"),
        }
    } else {
        match severity {
            Severity::Major => Ok((major.checked_add(1).ok_or_else(overflow)?, 0, 0)),
            Severity::Minor => Ok((major, minor.checked_add(1).ok_or_else(overflow)?, 0)),
            Severity::Patch => Ok((major, minor, patch.checked_add(1).ok_or_else(overflow)?)),
            Severity::None => unreachable!("callers return early on Severity::None before reaching this point"),
        }
    }
}

/// Parses a decimal prerelease counter from `suffix` -- the text remaining
/// after stripping a recognized tag/letter prefix from the current version's
/// raw string -- and returns it incremented by one. Returns `0` when there is
/// no such suffix (the current version doesn't carry this exact prefix, e.g.
/// it's a fresh prerelease or based on a different release) or the remainder
/// isn't a bare decimal number, both of which mean "start counting from 0".
fn next_counter(suffix: Option<&str>, overflow: impl Fn() -> BumpError) -> Result<u64, BumpError> {
    match suffix.and_then(|s| s.parse::<u64>().ok()) {
        Some(num) => num.checked_add(1).ok_or_else(overflow),
        None => Ok(0),
    }
}

